-- Disposable, credential-free PostgreSQL only. Never run on an existing DB.
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='public') THEN RAISE EXCEPTION 'Requires empty disposable database'; END IF; END $$;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE anon NOLOGIN;
CREATE ROLE service_role NOLOGIN BYPASSRLS;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
GRANT USAGE ON SCHEMA auth TO authenticated,anon;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,phone text,raw_user_meta_data jsonb,banned_until timestamptz);
CREATE TABLE auth.refresh_tokens(user_id text);
CREATE TABLE auth.sessions(user_id uuid);
CREATE TYPE public.member_status AS ENUM('joined','left','removed');
CREATE TYPE public.member_role AS ENUM('host','guest');
CREATE TYPE public.report_status AS ENUM('pending','reviewed','resolved','dismissed');
CREATE TABLE public.profiles(id uuid PRIMARY KEY,blocked_users uuid[] DEFAULT '{}',suspended_until timestamptz,email text);
CREATE TABLE public.admin_users(user_id uuid PRIMARY KEY);
CREATE TABLE public.admin_alert_recipients(alert_key text PRIMARY KEY,email text);
CREATE TABLE public.events(id uuid PRIMARY KEY,creator_user_id uuid,status text,start_time timestamptz,end_time timestamptz,max_invites int DEFAULT 7,member_count int DEFAULT 0,circle_id uuid,circle_visibility text,stranger_cap int);
CREATE TABLE public.event_members(event_id uuid,user_id uuid,status member_status,role member_role,age_at_join int,gender_at_join text,PRIMARY KEY(event_id,user_id));
CREATE TABLE public.user_blocks(id uuid DEFAULT gen_random_uuid(),blocker_id uuid,blocked_id uuid,UNIQUE(blocker_id,blocked_id));
CREATE TABLE public.event_interest_signals(id uuid DEFAULT gen_random_uuid(),event_id uuid,interested_user_id uuid,creator_id uuid,status text,expired_at timestamptz,expiry_reason text);
CREATE TABLE public.event_waitlist(event_id uuid,user_id uuid);
CREATE TABLE public.waitlist_notification_queue(event_id uuid,user_id uuid);
CREATE TABLE public.messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid,circle_id uuid,user_id uuid,content text,message_type text DEFAULT 'user',image_url text,audio_url text,mention_data jsonb);
CREATE TABLE public.message_reactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),message_id uuid,user_id uuid,emoji text);
CREATE TABLE public.circle_members(circle_id uuid,user_id uuid,status text);
CREATE FUNCTION public.is_circle_member(p_circle uuid,p_user uuid) RETURNS boolean LANGUAGE sql STABLE AS $$SELECT EXISTS(SELECT 1 FROM public.circle_members WHERE circle_id=p_circle AND user_id=p_user AND status='joined')$$;
CREATE FUNCTION public.private_chat_contact_allowed(p_circle uuid) RETURNS boolean LANGUAGE sql STABLE AS $$SELECT public.is_circle_member(p_circle,auth.uid())$$;
CREATE FUNCTION public.validate_chat_mention_document(p_content text,p_mentions jsonb) RETURNS jsonb LANGUAGE sql AS $$SELECT p_mentions$$;
CREATE FUNCTION public.is_admin(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=p_user)$$;
CREATE TABLE public.reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_user_id uuid,reported_user_id uuid,reported_event_id uuid,reported_message_id uuid,reason text,status report_status DEFAULT 'pending',details text,admin_notes text,created_at timestamptz DEFAULT now(),reviewed_at timestamptz,reviewed_by_admin_id uuid);
CREATE TABLE public.no_show_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid,reporter_user_id uuid,no_show_user_id uuid,created_at timestamptz DEFAULT now(),UNIQUE(event_id,reporter_user_id,no_show_user_id));
CREATE TABLE public.moderation_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action text,target_user_id uuid,target_email text,target_apple_sub text,reason text,performed_by uuid,metadata jsonb,performed_at timestamptz DEFAULT now());
CREATE TABLE public.moderation_automation_failures(operation text,target_user_id uuid,error_code text,error_message text);
CREATE TABLE public.banned_identifiers(email text,apple_sub text,phone_number text,reason text,banned_by uuid,banned_at timestamptz);
CREATE TABLE public.app_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid,type text,title text,body text,event_id uuid,status text DEFAULT 'unread',expires_at timestamptz);
-- Isolated cron/vault/net stubs never reach a network or real scheduler.
CREATE SCHEMA cron;
CREATE TABLE cron.job(jobid bigint GENERATED ALWAYS AS IDENTITY,jobname text PRIMARY KEY,schedule text,command text);
CREATE FUNCTION cron.schedule(p_name text,p_schedule text,p_command text) RETURNS bigint LANGUAGE plpgsql AS $$BEGIN INSERT INTO cron.job(jobname,schedule,command) VALUES(p_name,p_schedule,p_command) ON CONFLICT(jobname) DO UPDATE SET schedule=excluded.schedule,command=excluded.command; RETURN 1; END$$;
CREATE SCHEMA vault;
CREATE TABLE vault.decrypted_secrets(name text,decrypted_secret text);
CREATE SCHEMA net;
CREATE FUNCTION net.http_post(url text,body jsonb,headers jsonb) RETURNS bigint LANGUAGE sql AS $$SELECT 1::bigint$$;
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON profiles TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
ALTER TABLE user_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_blocks ON user_blocks TO authenticated USING(blocker_id=auth.uid()) WITH CHECK(blocker_id=auth.uid());
ALTER TABLE event_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_membership_update ON event_members FOR UPDATE TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_membership_insert ON event_members FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY read_membership ON event_members FOR SELECT TO authenticated USING(true);
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_messages ON messages FOR SELECT TO authenticated USING(public.is_admin(auth.uid()) OR EXISTS(SELECT 1 FROM event_members WHERE event_id=messages.event_id AND user_id=auth.uid() AND status='joined'));
CREATE POLICY insert_messages ON messages FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM event_members WHERE event_id=messages.event_id AND user_id=auth.uid() AND status='joined'));
CREATE POLICY edit_messages ON messages FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
ALTER TABLE reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_report_insert ON reports FOR INSERT TO authenticated WITH CHECK(reporter_user_id=auth.uid());
CREATE POLICY own_report_read ON reports FOR SELECT TO authenticated USING(reporter_user_id=auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO authenticated;
REVOKE INSERT,UPDATE,DELETE ON admin_users,admin_alert_recipients,moderation_actions FROM authenticated;
CREATE FUNCTION public.fixture_member_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN UPDATE public.events SET member_count=(SELECT count(*) FROM public.event_members WHERE event_id=NEW.event_id AND status='joined') WHERE id=NEW.event_id; RETURN NEW; END$$;
CREATE TRIGGER sync_count AFTER INSERT OR UPDATE ON event_members FOR EACH ROW EXECUTE FUNCTION public.fixture_member_count();
INSERT INTO profiles(id) SELECT ('00000000-0000-0000-0000-00000000000'||n)::uuid FROM generate_series(1,5)n;
INSERT INTO auth.users(id,email) SELECT id,CASE WHEN id='00000000-0000-0000-0000-000000000005' THEN 'fixture-admin@example.invalid' ELSE 'fixture@example.invalid' END FROM profiles;
INSERT INTO admin_users VALUES('00000000-0000-0000-0000-000000000005');
INSERT INTO admin_alert_recipients VALUES('default','fixture-admin@example.invalid');
