('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000001','completed',now()-interval '2 days',now()-interval '1 day');
INSERT INTO event_members SELECT e.id,p.id,'joined',CASE WHEN p.id=e.creator_user_id THEN 'host'::member_role ELSE 'guest'::member_role END,NULL,NULL FROM events e CROSS JOIN profiles p WHERE p.id<>'00000000-0000-0000-0000-000000000005';
